def caption(s):
 return ('Stage3A baseline'if not s['candidate']else'Stage3A.1 diagnostic pilot')+' | '+s['condition']+' | '+s['id']+' | '+('mobile'if s['mobile']else'desktop')
def add_text(doc,title,lines,width=430,height=760):
 p=doc.new_page(width=width,height=height);p.insert_textbox(fitz.Rect(24,25,width-24,94),title,fontsize=19,color=(.65,.10,.08))
 p.insert_textbox(fitz.Rect(24,108,width-24,height-35),'\n\n'.join(lines),fontsize=11,lineheight=1.35);return p
def add_shot(doc,s,phone=False):
 w,h=(430,760)if phone else(1440,1040);p=doc.new_page(width=w,height=h);p.insert_textbox(fitz.Rect(18,16,w-18,72),caption(s),fontsize=11 if phone else 18)
 rect=fitz.Rect(12,80,w-12,h-105)
 if phone:
  im=Image.open(R/s['file']).convert('RGB');im.thumbnail((1200,1600));import io;buf=io.BytesIO();im.save(buf,format='JPEG',quality=88);p.insert_image(rect,stream=buf.getvalue(),keep_proportion=True)
 else:p.insert_image(rect,filename=str(R/s['file']),keep_proportion=True)
 camera=s['data']['camera'];meta=f"Camera {s['position']}  FOV {camera['fov']} / DPR {s['data']['stats']['dpr']} / tier {s['data']['snapshot']['quality']}\n"+('Protected entry-route inspection. Neutral has NO PBR maps.'if s['condition']=='neutral'else'Approved dusk lighting. Geometry is NOT accepted.')
 p.insert_textbox(fitz.Rect(18,h-94,w-18,h-12),meta,fontsize=8 if phone else 12)
 return p
